def compute(vars):
    prior_year_additions = vars["v1"]
    current_year_additions = vars["v2"]
    difference = prior_year_additions - current_year_additions

    return {
        "value": round(difference),
        "trace": {
            "prior_year_additions": prior_year_additions,
            "current_year_additions": current_year_additions,
            "difference": difference,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": "amount"
            }
        }
    }
